use [SalesforceMigration]
go

WITH cols AS (
    SELECT
        [object_api_name],
        [column_list] = STRING_AGG('['+convert(varchar(max),[field_api_name])+'] nvarchar(1000)',', ')
            WITHIN GROUP (ORDER BY [object_api_name])
    FROM [ids].[sf_object_meta_ra] (nolock)
    where 1=1
    --and [object_api_name] not in ('AggregateResult','CronJobDetail','ContentBody','ContentTagSubscription','ContentWorkspaceSubscription','FormulaFunctionCategory','EngagementInterface')
    and [object_api_name] in ('Account')
    GROUP BY [object_api_name]
)
SELECT
    'CREATE TABLE [sfrhd].[' + [object_api_name] + '] (' + CHAR(13) + CHAR(10) +
    '    [dv_id] varbinary(16),' + CHAR(13) + CHAR(10) +
    '    [etl_loadts] datetime2,' + CHAR(13) + CHAR(10) +
    '    [external_id] varchar(1000),' + CHAR(13) + CHAR(10) +
    column_list + CHAR(13) + CHAR(10) +
    ');' + CHAR(13) + CHAR(13) AS create_table_sql
FROM cols
ORDER BY [object_api_name]
go
